#!/bin/bash
set -e
# Generated by `zfa package create-plugin` — publishes all packages in
# dependency order (app package first: the federated siblings declare it as
# a hosted dependency). Needs flutter/dart on PATH.
#
# pub.dev rate limits *new package creation* (4 in a few minutes), so the
# first publish of a federated family trips the limit on the last packages.
# That refusal is transient: it is retried with backoff instead of failing
# hard, and the first publishes of a never-registered family are spaced out.
# See https://github.com/arrrrny/zuraffa_inappwebview/issues/12 and
# scripts/publish_test.sh.

GREEN='\033[0;32m'; BLUE='\033[0;34m'; RED='\033[0;31m'; NC='\033[0m'

PUBLISH_MAX_ATTEMPTS="${PUBLISH_MAX_ATTEMPTS:-5}"
PUBLISH_RETRY_WAIT_SECS="${PUBLISH_RETRY_WAIT_SECS:-30}"
PUBLISH_NEW_PACKAGE_SPACING_SECS="${PUBLISH_NEW_PACKAGE_SPACING_SECS:-60}"

PACKAGES_IN_ORDER=("zuraffa_inappwebview" "zuraffa_inappwebview_platform" "zuraffa_inappwebview_android" "zuraffa_inappwebview_ios" "zuraffa_inappwebview_macos")
ROOT_DIR="$(cd "$(dirname "$0")/.." >/dev/null 2>&1; pwd -P)"

# True when the package is registered on pub.dev at all (any version).
is_registered_on_pub() {
    curl -s "https://pub.dev/api/packages/$1" | grep -q '"name"'
}

# dart pub publish --force, retrying pub.dev's new-package rate limit with
# backoff (same sleep pattern as the propagation loop below). Runs in the
# package directory. $1 = package name, $2 = version.
publish_with_retry() {
    local pkg="$1" version="$2" attempt=1 out status wait_secs
    while :; do
        out="$(dart pub publish --force 2>&1)" && status=0 || status=$?
        if [ "$status" -eq 0 ]; then
            printf '%s\n' "$out"
            return 0
        fi
        if printf '%s\n' "$out" | grep -q -e 'rate limit has been reached' -e '"package-created" operation is blocked'; then
            if [ "$attempt" -ge "$PUBLISH_MAX_ATTEMPTS" ]; then
                echo -e "${RED}pub.dev new-package rate limit still blocking $pkg after $attempt attempts.${NC}"
                printf '%s\n' "$out"
                return 1
            fi
            wait_secs=$(( PUBLISH_RETRY_WAIT_SECS * (1 << (attempt - 1)) ))
            if [ "$wait_secs" -gt 120 ]; then wait_secs=120; fi
            echo -e "${BLUE}pub.dev new-package rate limit hit on $pkg (attempt $attempt/$PUBLISH_MAX_ATTEMPTS) - retrying in ${wait_secs}s.${NC}"
            printf '%s\n' "$out"
            sleep "$wait_secs"
            attempt=$((attempt + 1))
            continue
        fi
        echo -e "${RED}Publish failed for $pkg${NC}"
        printf '%s\n' "$out"
        return 1
    done
}

LAST_PKG="${PACKAGES_IN_ORDER[${#PACKAGES_IN_ORDER[@]}-1]}"

for pkg in "${PACKAGES_IN_ORDER[@]}"; do
    version=$(grep "^version:" "$ROOT_DIR/packages/$pkg/pubspec.yaml" | sed 's/version: //' | tr -d '[:space:]')
    echo -e "${BLUE}=== Publishing $pkg $version ===${NC}"

    if curl -s "https://pub.dev/api/packages/$pkg" | grep -q "\"$version\""; then
        echo -e "${RED}$pkg $version is already on pub.dev - nothing to do.${NC}"; continue
    fi

    is_new_package=0
    if ! is_registered_on_pub "$pkg"; then
        is_new_package=1
    fi

    cd "$ROOT_DIR/packages/$pkg"
    dart pub publish --dry-run || { echo -e "${RED}Dry-run failed for $pkg${NC}"; exit 1; }
    publish_with_retry "$pkg" "$version" || exit 1

    # Wait for propagation before the dependents publish.
    for i in $(seq 1 30); do
        curl -s "https://pub.dev/api/packages/$pkg" | grep -q "$version" && break
        sleep 10
    done

    # Space the first publishes of a family that has never been registered on
    # pub.dev, so package creations stay inside the new-package rate limit.
    if [ "$is_new_package" -eq 1 ] && [ "$pkg" != "$LAST_PKG" ] && [ "$PUBLISH_NEW_PACKAGE_SPACING_SECS" -gt 0 ]; then
        echo -e "${BLUE}$pkg is a new pub.dev package - waiting ${PUBLISH_NEW_PACKAGE_SPACING_SECS}s before the next publish (pub.dev rate limit on new packages).${NC}"
        sleep "$PUBLISH_NEW_PACKAGE_SPACING_SECS"
    fi
done
echo -e "${GREEN}All packages published.${NC}"
